let guideContent={"schema_version":1,"chapters":[{"era":"Itä- ja Pohjois-Suomesta kaupunkiseuduille · Vuosaari 1966","title":"Työ löytyi kaupungista. Sinne piti rakentaa myös elämä.","text":"Suomen muutos on myös kertomus siitä, millaisista lähtökohdista ihminen voi rakentaa elämäänsä.","loop":["Työ muuttuu","Ovi toimeentuloon","Yhteiset ratkaisut","Mahdollisuus osallistua"],"phases":[{"title":"Millaisista oloista elämä alkaa?","text":"Toimeentulon ehdot voivat sitoa ihmisen lähtökohtiinsa tai avata uusia mahdollisuuksia."},{"title":"Uusi työ tarvitsee ympärilleen muutakin","text":"Työpaikan ympärille tarvitaan myös asunto, osaamista ja mahdollisuus pitää arki koossa."},{"title":"Avautuiko ovi kaikille?","text":"Yhden perheen muutto voi olla uusi alku. Toiselle sama muutos voi merkitä tutun työn, paikan ja yhteisön menettämistä. Auttoivatko yhteiset ratkaisut myös niitä, joille muutos oli vaikein?"}],"loop_notes":["Kun työn tekemisen tapa tai paikka muuttuu, myös arki joutuu liikkeeseen. Vanha taito tai tuttu asuinpaikka ei ehkä enää kanna samalla tavalla.","Uusi työ voi tuoda toimeentulon ja mahdollisuuden suunnitella tulevaa. Ovi ei silti avaudu jokaiselle yhtä helposti.","Asunto, koulutus ja yhteiset palvelut voivat tehdä mahdollisuudesta todellisen. Ilman niitä työ voi olla tarjolla, mutta ihmisen ulottumattomissa.","Kun ihminen pääsee mukaan, hän voi rakentaa elämäänsä ja varautua seuraavaan muutokseen. Jos mukaan pääsy jää toteutumatta, vaikea lähtötilanne voi seurata mukana."],"curve_notes":["Kun toimeentulo on sidoksissa maahan, satoon ja perheen asemaan, yhden huonon vuoden jälki voi ulottua pitkälle. Ihmisen ahkeruus ei yksin ratkaise, millaiset mahdollisuudet hänellä on.","Vähitellen yksittäisen perheen selviytymisestä tulee myös yhteinen kysymys: kuka saa oikeuksia, turvaa ja mahdollisuuden muuttaa omaa asemaansa? Päätös avaa oven vasta, kun se toteutuu arjessa."],"story_lines":["Toimeentulo riippui maasta ja sadosta.","Oikeuksien muutos saattoi avata uuden tien.","Työ siirtyi uusiin paikkoihin.","Ihmisten oli rakennettava arki uudelleen.","Asunto ja koulutus saattoivat auttaa alkuun.","Ilman niitä uusi työ saattoi jäädä ulottumattomiin.","Sama muutos saattoi avata yhden oven ja sulkea toisen."],"article_url":"./stories/suuri-muutto.html","preview_lines":["Työ löytyi yhä useammin kaupungista.","Työn perässä oli rakennettava myös uusi arki.","Lähtijöiden ja jääneiden tulevaisuudet erkanivat."],"range":[1960,1975]},{"era":"Suomi · vuonna 1992 valmistuneet ja laman jälkeiset vuodet","title":"Tutkinto valmistui vuonna 1992. Työura ei alkanut samalla tavalla.","text":"Laman jälki ei välttämättä katoa silloin, kun tuotanto alkaa elpyä.","loop":["Talous elpyy","Työ on muuttunut","Paluu ei ole sama","Jälki jää kannettavaksi"],"phases":[{"title":"Työn menetys voi katkaista elämässä monta asiaa","text":"Työttömyys ja velat voivat jättää suhdannekäännettä pidemmän jäljen."},{"title":"Paluu tapahtuu muuttuneeseen maailmaan","text":"Uudet työpaikat eivät välttämättä synny samoihin paikkoihin, samoilla ehdoilla tai samoille ihmisille."},{"title":"Kenelle elpyminen oli myös uusi alku?","text":"Joku pääsee takaisin työhön. Toinen kantaa pitkään velkaa, epävarmuutta tai katkenneen työuran seurauksia. Jos erot jäävät pysyviksi, sama kasvu voi kasvattaa hyvin erilaisia tulevaisuuksia."}],"loop_notes":["Tuotannon elpyminen voi herättää toivon: pahin olisi takana. Mutta toimeentulon menetys ei korjaannu pelkästä toivosta.","Palattava työ voi vaatia uudenlaista osaamista tai muuttoa. Se, mikä ennen riitti, ei ehkä enää avaa ovea.","Ikä, koulutus, terveys ja asuinpaikka voivat vaikuttaa siihen, kenelle paluu on mahdollinen. Sama kriisi voi siksi jättää erilaisen jäljen.","Jos paluu ei onnistu, seuraukset jäävät ihmisen, läheisten ja yhteisten järjestelmien kannettaviksi. Menneestä katkoksesta voi tulla seuraavan muutoksen lähtötilanne."],"curve_notes":["Kun työ katoaa, katoaa muutakin kuin palkka. Velkojen maksaminen vaikeutuu, arjen suunnitelmat horjuvat ja tulevaisuuden vaihtoehdot voivat kaventua.","Myöhemmin talous voi näyttää paremmalta. Ihmiselle ratkaisevaa on kuitenkin se, löytyykö hänelle paikka muuttuneessa työssä — vai jatkuuko poissaolo, vaikka muu yhteiskunta menee eteenpäin."],"story_lines":["Lama vei työn ja toimeentulon.","Talous alkoi myöhemmin elpyä.","Uusi työ ei ollut aina vanhan kaltainen.","Paluu saattoi vaatia muuttoa tai uusia taitoja.","Kaikilla ei ollut samoja mahdollisuuksia palata.","Velka ja katkennut työura saattoivat seurata mukana.","Kasvu palasi, mutta kaikki eivät päässeet takaisin jaloilleen."],"article_url":"./stories/laman-pitka-jalki.html","preview_lines":["Tutkinto valmistui keskellä lamaa.","Työuran alku jäi monella vaikeaksi.","Vaikea alku saattoi seurata pitkälle tulevaisuuteen."],"range":[1990,2008]},{"era":"Suomi ja Uusimaa · 2020–2022","title":"Ensin tulot horjuivat. Sitten arki kallistui.","text":"Kriisistä selviytyminen ja sen seurausten korjaaminen eivät ole sama asia.","loop":["Arki järkkyy","Ratkaisu tehdään","Vastuu vaihtaa paikkaa","Seuraus jatkuu"],"phases":[{"title":"Kriisi kohtaa ihmiset erilaisista lähtökohdista","text":"Puskuri, velka, terveys ja läheisten tuki voivat ratkaista, kuinka paljon liikkumavaraa jää."},{"title":"Säästö yhdessä kohdassa voi tuntua muualla","text":"Kun yhteinen tuki muuttuu, myös vastuu arjen koossa pitämisestä voi siirtyä."},{"title":"Loppuiko vaikeus vai vaihtoiko se paikkaa?","text":"Meno voi poistua yhdestä budjetista, mutta palata myöhemmin toisena tarpeena. Ratkaisun merkitys avautuu vasta, kun nähdään, mitä ihmisen mahdollisuuksille tapahtui ajan kuluessa."}],"loop_notes":["Kun hinnat tai korot nousevat, liikkumavara voi huveta nopeasti. Eri kriisit koskettavat eri ihmisiä ja arjen eri osia.","Tilanteeseen vastataan päätöksillä. Ne voivat turvata selviytymistä tai muuttaa sitä, millaista apua on saatavilla.","Jos tuki vähenee, ihmisen ja hänen läheistensä on ehkä kannettava enemmän. Kaikilla ei ole samaa voimaa, aikaa tai rahaa ottaa vastuuta vastaan.","Vaikeus voi näkyä vasta myöhemmin työn menetyksenä, hoidon tarpeena tai kaventuneena arkena. Onnistunut ratkaisu voi myös estää tämän kierteen."],"curve_notes":["Pandemia, sota, kallistuvat hinnat ja korot järkyttävät arkea eri tavoin. Samakin noussut meno voi olla yhdelle harmi ja toiselle raja, jonka jälkeen arki ei enää pysy koossa.","Kun yhteisiä menoja sovitetaan uuteen tilanteeseen, myös ihmisten mahdollisuudet voivat muuttua. Missä säästö syntyy, ja missä sen seuraukset alkavat näkyä?"],"story_lines":["Kriisi järkytti arkea.","Yhteisiä menoja alettiin sopeuttaa.","Päätös muutti sitä, millaista tukea sai.","Vastuu saattoi siirtyä ihmiselle ja läheisille.","Kaikilla ei ollut voimia kantaa sitä.","Säästö saattoi palata myöhemmin uutena avuntarpeena.","Ratkaisevaa oli, helpottiko vaikeus vai siirtyikö se eteenpäin."],"article_url":"./stories/kriisin-lasku.html","preview_lines":["Vuonna 2020 toimeentulo horjui.","Vuonna 2022 arki kallistui.","Turvan merkitys näkyi siinä, miten arki kantoi."],"range":[2020,2025]},{"era":"Suomi · ehdollinen tulevaisuuspolku vuodesta 2025 eteenpäin","title":"Entä jos työ joustaisi ennen kuin ihminen putosi sen ulkopuolelle?","text":"Muuttuva työnjako voisi avata osallistumista myös niille, joille nykyiset ehdot ovat liian ahtaat.","loop":["Tehtäville uusi muoto","Mahdollinen oma paikka","Tuki kantaa mukana","Mahdollisuus jatkaa"],"phases":[{"title":"Kaikki eivät mahdu samoihin työn ehtoihin","text":"Ihmisellä voi olla annettavaa, vaikka valmiiksi rajatun työn ehdot eivät sovi hänen tilanteeseensa."},{"title":"Oma paikka voi syntyä työn järjestämisestä","text":"Tehtävien, työajan ja tuen yhdistelmä voisi tehdä osallistumisesta mahdollista myös tavallisessa arjessa."},{"title":"Avautuuko mahdollisuus, jota voi jatkaa?","text":"Hyvä alku ei vielä riitä. Osallistumisen pitäisi olla mielekästä ja kestävää myös ihmiselle itselleen. Jos järjestely kuormittaa liikaa tai jää väliaikaiseksi, oma paikka voi kadota uudelleen."}],"loop_notes":["Tehtävät voisi järjestää niin, ettei jokaisen tarvitse selvitä samasta kokonaisuudesta samalla tavalla. Muutos alkaisi työn ehdoista.","Sopiva tehtävä ja mahdollinen työaika voisivat avata oman paikan. Osallistuminen olisi enemmän kuin pelkkä vaatimus olla mukana.","Tuki voisi auttaa pitämään arjen ja toimintakyvyn koossa. Sen tehtävä olisi kantaa osallistumista, ei tehdä siitä uutta selviytymiskoetta.","Jos järjestely toimii, ihmiselle voisi avautua mahdollisuus jatkaa omista lähtökohdistaan. Jos se ei toimi, myös työn ja tuen ehtoja pitäisi muuttaa."],"curve_notes":["Työn tehtävät muuttuvat jälleen. Muutos voi sulkea vanhoja ovia, mutta se voi myös antaa tilaisuuden järjestää tekeminen toisin.","Oma paikka voisi rakentua siitä, mitä ihminen pystyy tekemään, eikä vain siitä, mihin valmiiseen työrooliin hänen pitäisi sopia. Tämä on mahdollinen suunta, ei lupaus."],"story_lines":["Työn vanhat ehdot eivät sopineet kaikille.","Tehtävät voitaisiin järjestää toisin.","Sopiva tehtävä voisi avata oman paikan.","Sopiva työaika voisi tehdä osallistumisesta mahdollista.","Tuki voisi auttaa arkea kantamaan.","Osallistuminen voisi jatkua ilman kohtuutonta kuormaa.","Mahdollisuus syntyisi, jos työ joustaisi ihmisen mukana."],"article_url":"./stories/tyo-joustaa.html","preview_lines":["Kaikki eivät mahtuneet samoihin työn ehtoihin.","Tehtäviä ja tukea voitaisiin järjestää toisin.","Oma paikka voisi syntyä, jos työ joustaisi ihmisen mukana."],"range":[2025,2060]}]};
try{const response=await fetch(new URL('./murrokset1-guide.json',import.meta.url),{cache:'no-cache'});if(response.ok){const data=await response.json();if(data.schema_version===1&&Array.isArray(data.chapters)&&data.chapters.length===4&&data.chapters.every(c=>typeof c.title==='string'&&typeof c.text==='string'&&typeof c.article_url==='string'&&c.article_url.startsWith('./stories/')&&Array.isArray(c.preview_lines)&&c.preview_lines.length===3&&c.preview_lines.every(line=>typeof line==='string')&&Array.isArray(c.phases)&&c.phases.length===3&&c.phases.every(p=>typeof p.title==='string'&&typeof p.text==='string')))guideContent=data;}}catch{}
// END GUIDE LOADER
const storyContent=[{"slug":"suuri-muutto","title":"Työ löytyi kaupungista. Sinne piti rakentaa myös elämä.","place":"Itä- ja Pohjois-Suomesta kaupunkiseuduille · Vuosaari 1966","kind":"Historiallinen kertomus","lead":"Suuri muutto siirsi ihmisiä työn perässä. Muuttajan mahdollisuus ei kuitenkaan päättynyt työpaikan löytymiseen: uuden työn ympärille oli rakennettava toimiva arki.","sections":[["Kun tulevaisuus löytyi muualta",[["1960-luvun Suomessa maaseudulta lähdettiin kaupunkeihin ja myös Ruotsiin työn perässä. Talouden painopiste siirtyi maataloudesta teollisuuteen ja palveluihin. Tämä oli muutos siinä, mistä palkka ja elanto löytyivät, mutta samalla siinä, missä elämää saattoi rakentaa. Lähteminen ei ollut kaikille samanlainen valinta: uuden mahdollisuuden rinnalla oli irtauduttava tutusta ympäristöstä.",[1]],["Tilastokeskuksen pitkän aikavälin tarkastelussa Itä- ja Pohjois-Suomen muuttotappio oli 1960- ja 1970-luvuilla yhteensä noin 200 000 ihmistä. Luku kertoo muutoksen mittakaavasta. Se ei kerro, miten yksittäinen lähtijä pärjäsi, mutta auttaa ymmärtämään, miksi lähtöalueiden ja vastaanottavien kaupunkien kysymykset olivat erilaisia.",[2]]]],["Vuosaari: mahdollisuus tarvitsi asunnon",[["Vuosaari liitettiin Helsinkiin vuonna 1966. Entinen huvila- ja teollisuusalue muuttui lähiöksi. Asuntosäästäjät ry oli perustettu vuonna 1957 helpottamaan muun muassa palkansaajien ja nuorten omistusasunnon hankintaa; yhdistys rakennutti noin kolme neljäsosaa Vuosaaren 1960-luvun rakennuskannasta. Kaupungin kasvu näkyi konkreettisesti taloina ja uusina asuinalueina.",[3]],["Tässä tulee näkyviin yhteiskuntajärjestelmän tehtävä. Työ ja asuminen eivät olleet kaksi toisistaan irrallista asiaa. Työpaikan vastaanottamiseen tarvittiin paikka, josta työssä saattoi käydä. Kertomuksen tulkinta on, että rakennemuutos alkoi kantaa ihmisen arjessa vasta, kun nämä edellytykset sopivat yhteen. Pelkkä uusien asuntojen määrä ei kuitenkaan osoita, että jokaisella muuttajalla oli niihin varaa.",[]]]],["Lähtijä ja jäänyt elivät eri muutosta",[["Muuttovoitto ja muuttotappio olivat saman tapahtuman kaksi puolta. Vastaanottavalla alueella tarvittiin tilaa uusille asukkaille. Lähtöalueella väestön väheneminen muutti paikallisen elämän edellytyksiä. Näistä alueellisista havainnoista ei voi suoraan päätellä, että jokaisen lähtijän tilanne parani tai jokaisen jääneen heikkeni.",[]],["Siksi suuren muuton ankkuri kysyy myös, kuka pystyi tarttumaan uuteen työhön. Ikä, perheen vastuut, osaaminen ja asumisen hinta ovat mahdollisia eroja selittäviä tekijöitä. Niiden merkitys tarvitsee erillistä aineistoa; niitä ei tässä esitetä dokumentoidun perheen elämänvaiheina.",[]],["Iso kuva on työn ja elämän sijainnin yhteensovittaminen. Tuotanto saattoi kasvaa yhdessä paikassa, mutta muuttajan oli saatava myös arkensa toimimaan siellä. Tämä sama kysymys palasi myöhemmin, kun työ jälleen muuttui: oliko ihmisellä todellinen mahdollisuus seurata sitä?",[]]]]],"sources":[["Tilastokeskus: Suomi pääsi länsimaisen kulutuksen makuun 1960-luvulla","https://stat.fi/tietotrendit/artikkelit/2018/suomi-paasi-lansimaisen-kulutuksen-makuun-1960-luvulla"],["Tilastokeskus: Maassamuuton suuri linja 1880-luvulta lähtien","https://stat.fi/artikkelit/2007/art_2007-07-13_001.html?s=0"],["Helsingin kaupunki: Vuosaari, Juha Vuorinen 2021","https://historia.hel.fi/fi/alueet/itainen/vuosaari"]]},{"slug":"laman-pitka-jalki","title":"Tutkinto valmistui vuonna 1992. Työura ei alkanut samalla tavalla.","place":"Suomi · vuonna 1992 valmistuneet ja laman jälkeiset vuodet","kind":"Historiallinen kertomus","lead":"Lama katkaisi työuria, mutta myös vaikeutti niiden alkamista. Vuonna 1992 valmistuneiden asema näyttää, miksi talouden palautuminen ja ihmisen palautuminen olivat eri kysymyksiä.","sections":[["Valmistuminen osui sulkeutuvaan oveen",[["Suomessa vuonna 1992 valmistunut nuori tuli työmarkkinoille keskellä lamaa. Tutkinto oli valmis, mutta työpaikan löytyminen oli vaikeaa. Tämä ei ole yhden nimetyn nuoren muistelma: kertomuksen lähtökohtana on Tilastokeskuksen vertailu vuonna 1992 ja vuonna 2002 tutkinnon suorittaneista. Vertailu tuo näkyviin valmistumisajankohdan ja työmarkkinatilanteen merkityksen.",[1]],["Tilastokeskuksen aineistossa vuoden 1992 valmistuneiden työllistyminen vuoden kuluessa oli selvästi heikompaa kuin vuonna 2002 valmistuneiden. Ammatillisen tutkinnon suorittaneista naisista työllisiä oli 40 prosenttia vuoden 1992 ryhmässä ja 70 prosenttia vuoden 2002 ryhmässä. Sama koulutusaste ei siis tarkoittanut samanlaista työuran alkua eri aikoina.",[1]]]],["Vaikea alku saattoi seurata mukana",[["Vuonna 1992 valmistuneista 10,5 prosenttia oli tarkastelun mukaan työttömänä vielä viiden vuoden kuluttua. Tässä seurannassa olivat mukana ne, joiden korkein tutkinto oli pysynyt samana. Rajaus on tärkeä: tulos ei kuvaa kaikkia valmistuneita samalla tavalla eikä osoita, että samat ihmiset olisivat olleet yhtäjaksoisesti työttöminä koko ajan.",[1]],["Kertomuksen tutkittava mekanismi on vaikean alun kasautuminen. Työssä kertynyt kokemus, tulot ja mahdollisuus suunnitella elämää voivat vaikuttaa seuraaviin mahdollisuuksiin. Jos ensimmäinen askel jää ottamatta, seuraava askel voi olla vaikeampi. Tämä on tulkinta, jota kohorttien erot auttavat tutkimaan; vertailu yksin ei erottele kaikkia erojen syitä.",[]]]],["Kaikki ikäryhmät eivät palanneet samaan lähtökohtaan",[["Tilastokeskuksen vuonna 2012 julkaistu työurien tarkastelu kuvasi myös eri syntymäkohorttien erilaista toipumista lamasta. Laman aikana nuorempien kohorttien työllisyys palautui tarkastelussa enemmän kuin vanhempien. Tulos kiinnittää huomion siihen, missä elämänvaiheessa kriisi kohdattiin. Se on kyseisen aineiston ja julkaisuajankohdan havainto, ei väite kaikkien kohorttien nykytilanteesta.",[2]],["Yhteiskunnan kannalta kysymys ulottui suhdanteen yli. Työn puuttuminen vaikutti siihen, millaisia mahdollisuuksia ihmiselle kertyi ja millaista tukea hän tarvitsi. Talous saattoi elpyä samalla kun työuran katkos jatkoi vaikuttamistaan. Yhteisiä ratkaisuja arvioitaessa olisi siksi nähtävä myös palautumisen ehdot, ei vain kasvun käynnistyminen.",[]],["Laman ankkuri nostaa esiin yhden pitkän aikavälin kysymyksen: korjautuiko menetetty mahdollisuus myöhemmin vai muuttuiko se seuraavan vaiheen lähtökohdaksi? Vastaus tarvitsee ryhmittäistä seurantaa ja vaihtoehtoisia selityksiä, kuten koulutuksen, toimialojen ja alueiden muutoksia.",[]]]]],"sources":[["Tilastokeskus: Lamavuonna 1992 tutkinnon suorittaneet työllistyivät huonosti, 2012","https://stat.fi/artikkelit/2012/art_2012-03-12_006.html"],["Tilastokeskus: Hyvin koulutetuilla pisimmät työurat, 2012","https://stat.fi/artikkelit/2012/art_2012-03-12_007.html?s=4"]]},{"slug":"kriisin-lasku","title":"Ensin tulot horjuivat. Sitten arki kallistui.","place":"Suomi ja Uusimaa · 2020–2022","kind":"Historiallinen kertomus","lead":"Pandemia ja hintojen nousu muuttivat toimeentulon ehtoja eri tavoin. Yhteiskunnan vastuu tuli näkyviin siinä, miten arjen jatkuvuutta kannateltiin muutoksen yli.","sections":[["Vuonna 2020 tuttu tulonlähde saattoi katketa",[["Koronakriisi lisäsi vuonna 2020 Kelan työttömyysturvan tarvetta. Saajia oli noin 412 000, joista noin 44 000 sai yrittäjien työmarkkinatukea. Yrittäjät mukaan lukien saajien määrä kasvoi edellisvuodesta noin 24 prosenttia; ilman heitä kasvu oli noin 11 prosenttia. Luvut kuvaavat etuuden saajia, eivät koko maan työttömien määrää.",[1]],["Uudellamaalla kasvu oli erityisen suuri: yrittäjät mukaan lukien työttömyysturvan saajia oli noin 40 prosenttia enemmän kuin vuonna 2019. Vaikutus ei siten jakautunut alueille samalla tavalla. Tämä alueellinen havainto ei vielä kerro yksittäisen perheen selviytymisestä, mutta osoittaa, missä toimeentulon kannattelun tarve kasvoi.",[1]]]],["Vuonna 2022 sama raha riitti vähempään",[["Pandemian jälkeen kotitaloudet kohtasivat uudenlaisen paineen. Vuoden 2022 keskimääräinen inflaatio oli Suomessa 7,1 prosenttia. Joulukuun hinnannousua vauhdittivat Tilastokeskuksen mukaan muun muassa sähkö ja lainojen korot. Kyse oli eri tapahtumasta kuin pandemian aikaisesta työn ja tulojen katkoksesta.",[2]],["Tilastokeskuksen kulutusta käsitellyt kirjoitus kuvasi, miten pandemia muutti kulutuksen rakennetta: kodin ulkopuolisia palveluja käytettiin vähemmän ja kotona tapahtuva kulutus korostui. Hintojen myöhempi nousu kohtasi siis jo muuttuneen arjen. Keskimääräinen kuluttajahintaindeksi ei silti ole jokaisen kotitalouden oma hinnannousu.",[3]]]],["Turva oli yhteys kriisin ja arjen välillä",[["Näiden tapahtumien rinnakkainen tarkastelu tekee yhteiskunnan tehtävän konkreettiseksi. Kun palkkatulo puuttui, tarvittiin keinoja pitää arkea koossa. Kun välttämättömät menot nousivat, ratkaisevaa oli, millaista liikkumavaraa jäljellä oli. Sama meno saattoi olla eri kotitalouksille hyvin erilainen rasitus.",[]],["Kertomuksen tulkinta on, että kriisin seuraukset riippuivat myös sen yli kantavista järjestelyistä. Tästä ei seuraa, että jokainen etuus esti myöhemmän vaikeuden tai että jokainen säästö lisäsi sitä. Päätöksen vaikutus pitäisi erottaa kriisin suorasta vaikutuksesta ja perheen aiemmasta tilanteesta.",[]],["Iso kuva koskee vastuun jakautumista ajan kuluessa. Jos vaikeus helpottui, yhteinen ratkaisu saattoi katkaista kasautumisen. Jos vaikeus vain siirtyi, seuraukset saattoivat tulla vastaan myöhemmin toisessa muodossa. Tämän ankkurin avoin kysymys on, millä ryhmillä turva kantoi ja millä ryhmillä se jäi riittämättömäksi.",[]]]]],"sources":[["Kela: Etuuksien saajat vuonna 2020","https://koronamittarit.kela.fi/posts/2021-01-25-custom-1fi/"],["Tilastokeskus: Inflaatio 9,1 % joulukuussa 2022","https://stat.fi/fi/julkaisu/cl8bkshgb6g8z0bw0h415hbnu"],["Tilastokeskus: Pandemia ja inflaatio ovat myllänneet kotitalouksien kulutusta, 2023","https://stat.fi/tietotrendit/blogit/2023/pandemia-ja-inflaatio-ovat-myllanneet-kotitalouksien-kulutusta"]]},{"slug":"tyo-joustaa","title":"Entä jos työ joustaisi ennen kuin ihminen putosi sen ulkopuolelle?","place":"Suomi · ehdollinen tulevaisuuspolku vuodesta 2025 eteenpäin","kind":"Ehdollinen tulevaisuuskertomus","lead":"Tämä kertomus ei kuvaa tapahtunutta uudistusta eikä ennusta sen tulosta. Se tutkii vaihtoehtoa: voisiko työn ja tuen ehtojen muuttaminen avata osallistumista, joka muuten jäisi toteutumatta?","sections":[["Ongelma saattoi olla myös työn ehdoissa",[["Kuviteltu tilanne oli arkinen: ihminen pystyi tekemään osan tehtävistä, mutta ei koko työroolia entisillä ehdoilla. Vaihtoehdoksi jäi liian helposti joko selviytyä kokonaisuudesta tai jäädä sen ulkopuolelle. Tämä ei ole nimetyn henkilön tapaus vaan tulevaisuuspolun lähtötilanne, jolla tehdään päätöskysymys ymmärrettäväksi.",[]],["Työn muokkaus ei kuitenkaan ole uusi tai pelkästään kuvitteellinen ajatus. Työterveyslaitoksen ohjeissa muokkauksen kohteita ovat muun muassa tehtävät, työaika ja työympäristö. Työn voimavaroja voidaan myös vahvistaa. Laitoksen mukaan työn muokkaus voi tukea työssä jatkamista erilaisissa toimintakykyä rajoittavissa tilanteissa.",[1,2]]]],["Tehtävä, aika ja tuki voisivat muodostaa oman paikan",[["Tulevaisuuspolussa työ jaettaisiin uudelleen. Ihmiselle sopiva tehtävä yhdistettäisiin mahdolliseen työaikaan ja tarpeelliseen tukeen. Tarkoituksena ei olisi lisätä vaatimusta osallistua, vaan muuttaa niitä ehtoja, jotka tekevät osallistumisesta mahdollista. Työn hyödyllisyyden, toimeentulon ja ihmisen oman tahdon pitäisi kuulua samaan arviointiin.",[]],["Tällainen järjestely voisi auttaa jo työssä olevaa jatkamaan. On kuitenkin eri kysymys, voisiko se avata työtä myös pitkäksi aikaa työelämän ulkopuolelle jääneille. Työssä jatkamista koskeva näyttö ei sellaisenaan todista jälkimmäistä. Uusi polku tarvitsisi omat toteutusehtonsa ja oman arviointinsa.",[]]]],["Hyvä alku ei vielä ollut pysyvä mahdollisuus",[["Jos osallistuminen käynnistyisi, seurannassa pitäisi katsoa muutakin kuin ensimmäistä työpäivää. Kantoiko arki, oliko tekeminen mielekästä ja pysyikö kuormitus mahdollisena? Myös toimeentulo, kustannukset ja tuen jatkuvuus vaikuttaisivat siihen, syntyikö ihmiselle todellinen oma paikka.",[]],["Yhteiskuntajärjestelmän kysymys olisi silloin, kohdistuivatko ratkaisut vain työstä puuttuvan tulon korvaamiseen vai myös osallistumisen ehtojen muuttamiseen. Nämä tehtävät eivät sulje toisiaan pois. Turva voi olla juuri se edellytys, jonka varassa uusi mahdollisuus voidaan ottaa vastaan.",[]],["Tarinan ehdollinen lopputulos on selvä: työ voisi avata paikan useammalle, jos sen ehdot joustaisivat toimintakyvyn mukana. Mutta jos tehtävä ei olisi sopiva, tuki katkeaisi tai toimeentulo heikkenisi, järjestely voisi epäonnistua. Silloin muutettava olisi myös suunnitelmaa, ei vain osallistujan toimintaa.",[]]]]],"sources":[["Työterveyslaitos: Keinoja työn muokkaukseen","https://www.ttl.fi/oppimateriaalit/mieli-ja-tyon-muokkaus/miten-muokata-tyota/keinoja-tyon-muokkaukseen"],["Työterveyslaitos: Työkyvyn tuen keinot","https://www.ttl.fi/oppimateriaalit/tyokyvyn-tuki/tyokyvyn-tuen-keinot"]]}];
